START TRANSACTION;

CREATE TABLE "MentorAbuseReports" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ReporterId" integer NOT NULL,
    "TargetUserId" integer NOT NULL,
    "MentorBookingId" integer,
    "Category" character varying(64) NOT NULL,
    "Description" character varying(1000) NOT NULL,
    "Status" character varying(32) NOT NULL,
    "AdminNotes" character varying(1000),
    "ReviewedByAdminId" integer,
    "ReviewedAtUtc" timestamp without time zone,
    "CreatedAtUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_MentorAbuseReports" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MentorAbuseReports_MentorBookings_MentorBookingId" FOREIGN KEY ("MentorBookingId") REFERENCES "MentorBookings" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_MentorAbuseReports_Users_ReporterId" FOREIGN KEY ("ReporterId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorAbuseReports_Users_TargetUserId" FOREIGN KEY ("TargetUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "MentorDisputes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MentorBookingId" integer NOT NULL,
    "LearnerId" integer NOT NULL,
    "MentorId" integer NOT NULL,
    "Category" integer NOT NULL,
    "Status" integer NOT NULL,
    "Reason" character varying(1000) NOT NULL,
    "EvidenceUrls" character varying(2000),
    "MentorResponse" character varying(1000),
    "MentorRespondedAtUtc" timestamp without time zone,
    "AdminNotes" character varying(1000),
    "AdminDecision" character varying(100),
    "IsRefundApproved" boolean,
    "CreditRefunded" boolean NOT NULL,
    "RefundOperationKey" character varying(128),
    "ResolvedByAdminId" integer,
    "ResolvedAtUtc" timestamp without time zone,
    "CreatedAtUtc" timestamp without time zone NOT NULL,
    "UpdatedAtUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_MentorDisputes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MentorDisputes_MentorBookings_MentorBookingId" FOREIGN KEY ("MentorBookingId") REFERENCES "MentorBookings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorDisputes_Users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorDisputes_Users_MentorId" FOREIGN KEY ("MentorId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorDisputes_Users_ResolvedByAdminId" FOREIGN KEY ("ResolvedByAdminId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "MentorReviews" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MentorBookingId" integer NOT NULL,
    "MentorId" integer NOT NULL,
    "LearnerId" integer NOT NULL,
    "Rating" integer NOT NULL,
    "Comment" character varying(1000),
    "IsPublic" boolean NOT NULL,
    "ModerationStatus" integer NOT NULL,
    "MentorReply" character varying(1000),
    "MentorRepliedAtUtc" timestamp without time zone,
    "CreatedAtUtc" timestamp without time zone NOT NULL,
    "UpdatedAtUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_MentorReviews" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_MentorReview_Rating_Range" CHECK ("Rating" >= 1 AND "Rating" <= 5),
    CONSTRAINT "FK_MentorReviews_MentorBookings_MentorBookingId" FOREIGN KEY ("MentorBookingId") REFERENCES "MentorBookings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorReviews_Users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorReviews_Users_MentorId" FOREIGN KEY ("MentorId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "MentorDisputeHistories" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "DisputeId" integer NOT NULL,
    "Action" character varying(64) NOT NULL,
    "PreviousStatus" integer,
    "NewStatus" integer NOT NULL,
    "ActorId" integer NOT NULL,
    "ActorRole" character varying(32) NOT NULL,
    "Notes" character varying(1000),
    "CreatedAtUtc" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_MentorDisputeHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MentorDisputeHistories_MentorDisputes_DisputeId" FOREIGN KEY ("DisputeId") REFERENCES "MentorDisputes" ("Id") ON DELETE CASCADE
);

