CREATE INDEX "IX_MentorDisputes_MentorBookingId" ON "MentorDisputes" ("MentorBookingId");

CREATE INDEX "IX_MentorDisputes_MentorId" ON "MentorDisputes" ("MentorId");

CREATE INDEX "IX_MentorDisputes_ResolvedByAdminId" ON "MentorDisputes" ("ResolvedByAdminId");

CREATE INDEX "IX_MentorDisputes_Status" ON "MentorDisputes" ("Status");

CREATE INDEX "IX_MentorReviews_LearnerId" ON "MentorReviews" ("LearnerId");

CREATE INDEX "IX_MentorReviews_Mentor_Public_Status" ON "MentorReviews" ("MentorId", "IsPublic", "ModerationStatus");

